import numpy as np
import pandas as pd

# Constants
COLUMNS = ['Column1', 'Column2', 'Column3', 'Column4', 'Column5']

def task_func(length, min_value=0, max_value=100):
    if length < 0:
        raise ValueError("length must be non-negative")
    if min_value > max_value:
        raise ValueError("min_value must be less than or equal to max_value")

    data = np.random.randint(min_value, max_value + 1, size=(length, len(COLUMNS)))
    df = pd.DataFrame(data, columns=COLUMNS)

    if length == 0:
        return pd.DataFrame(columns=COLUMNS)

    values = pd.Index(range(min_value, max_value + 1))
    cdf = pd.DataFrame(index=values)

    for column in COLUMNS:
        counts = df[column].value_counts().reindex(values, fill_value=0).sort_index()
        cdf[column] = counts.cumsum() / length

    return cdf
